referenceSolutionTemplate:
#include <stdio.h>
#include <string.h>

int main(void) {
    char left[] = "{x}";
    char right[] = "{y}";

    if (strcmp(left, right) == 0) {
        printf("一样喵\n");
    } else {
        printf("不一样喵\n");
    }
    return 0;
}
